override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    // Always enable WebView remote-debug so a desktop Chrome can inspect
    // the rendered DOM via chrome://inspect. Harmless in release: the
    // page is only reachable from the same device.
    WebView.setWebContentsDebuggingEnabled(true)
    val supported = WebViewFeature.isFeatureSupported(WebViewFeature.ALGORITHMIC_DARKENING)
    Log.i(TAG, "onWebViewCreate fired; ALGORITHMIC_DARKENING supported=$supported")
    if (supported) {
        WebSettingsCompat.setAlgorithmicDarkeningAllowed(webView.settings, true)
        Log.i(TAG, "setAlgorithmicDarkeningAllowed(true) applied to WebView settings")
    }
    // Diagnostic: ~5s after the page has loaded, query
    // `prefers-color-scheme` + count `<meta name="color-scheme">` tags
    // so we can confirm whether the WebView is reporting dark and
    // whether the Dioxus-emitted meta tag landed in the DOM.
    webView.postDelayed({
        webView.evaluateJavascript(
            """
            (function () {
                var pcs = window.matchMedia('(prefers-color-scheme: dark)').matches;
                var metas = document.querySelectorAll('meta[name="color-scheme"]').length;
                var bg = window.getComputedStyle(document.body).backgroundColor;
                return JSON.stringify({pcs: pcs, metas: metas, bg: bg});
            })();
            """.trimIndent()
        ) { result ->
            Log.i(TAG, "WebView color-scheme probe: $result")
        }
    }, 5000)
}

