        // to confirm the early-injection actually flipped
        // `prefers-color-scheme: dark` to true when the device is in
        // dark mode.
        webView.postDelayed({
            webView.evaluateJavascript(
                """
                (function () {
                    var pcs = window.matchMedia('(prefers-color-scheme: dark)').matches;
