                })();
                """.trimIndent()
            ) { result ->
                Log.i(TAG, "WebView color-scheme probe: $result")
            }
        }, 5000)
    }

    companion object {
        private const val REQUEST_CODE_POST_NOTIFICATIONS = 1001
        private const val TAG = "RiverMainActivity"
    }
}

